import { withRetry } from "./retry.js";

export class HttpError extends Error {
  constructor(status) {
    super(`HTTP ${status}`);
    this.status = status;
  }
}

// Fetches JSON from url; network errors are retried.
export async function getJson(url, { fetchImpl = fetch, attempts = 3, sleep } = {}) {
  const response = await withRetry(() => fetchImpl(url), { attempts, sleep });
  if (!response.ok) throw new HttpError(response.status);
  return response.json();
}

