import test from "node:test";
import assert from "node:assert/strict";
import { getJson, HttpError } from "../src/client.js";

const reply = (status, body = {}) => ({ ok: status < 400, status, json: async () => body });
const noSleep = async () => {};

test("returns the JSON body", async () => {
  const fetchImpl = async () => reply(200, { a: 1 });
  assert.deepEqual(await getJson("/a", { fetchImpl, sleep: noSleep }), { a: 1 });
});

test("throws HttpError on a 404", async () => {
  const fetchImpl = async () => reply(404);
  await assert.rejects(getJson("/a", { fetchImpl, sleep: noSleep }), HttpError);
});

